import Foundation
import RingProtocol

/// A paired ring as the app knows it. Deliberately holds no advertised name, Bluetooth address or
/// serial number: `id` is generated by the app, and the rest is what the ring reports about itself.
public struct StoredRing: Equatable, Sendable {
    public var id: UUID
    /// Protocol family, for example `ycbt`.
    public var protocolFamily: String
    public var model: String?
    public var firmware: String?
    /// Whole milliseconds.
    public var firstSeenAt: Date
}

/// A history transfer as saved, with its row id and owning ring.
public struct StoredTransfer: Equatable, Sendable {
    public var id: Int64
    public var ringID: UUID
    public var transfer: HistoryTransfer
}

public enum InsertOutcome: Equatable, Sendable {
    /// A new row was written.
    case inserted(id: Int64)
    /// The same ring, kind and data bytes were already stored; the first row was kept.
    case duplicate(existingID: Int64)
}

/// One time the app set the ring's clock. The ring stamps records with whatever clock was last
/// set and does not follow travel or daylight saving, so ingestion needs the offset that was in
/// force when a record was stamped.
public struct ClockSetEvent: Equatable, Sendable {
    public var ringID: UUID
    /// The instant the clock was set. Whole milliseconds.
    public var instant: Date
    public var timeZoneIdentifier: String
    /// The UTC offset in seconds that was sent to the ring.
    public var utcOffsetSeconds: Int

    public init(ringID: UUID, instant: Date, timeZoneIdentifier: String, utcOffsetSeconds: Int) {
        self.ringID = ringID
        self.instant = instant
        self.timeZoneIdentifier = timeZoneIdentifier
        self.utcOffsetSeconds = utcOffsetSeconds
    }
}

public enum RingStoreError: Error, Equatable, Sendable {
    case unknownRing(UUID)
    /// A stored value could not be read back (for example an unknown history kind name).
    case corruptRow(String)
}
